package com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.sharedKernel.businesslogic.commandStatus.BusinessCommandRejectedException;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.*;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.command.CommandHandler;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.gateways.*;import jakarta.transaction.Transactional;
public class RemoveAvatarCommandHandler implements CommandHandler<RemoveAvatarCommand>{private final AppUserRepository users;private final AvatarMediaRepository media;private final DomainEventPublisher events;private final DateTimeProvider clock;public RemoveAvatarCommandHandler(AppUserRepository users,AvatarMediaRepository media,DomainEventPublisher events,DateTimeProvider clock){this.users=users;this.media=media;this.events=events;this.clock=clock;}@Override@Transactional public void execute(RemoveAvatarCommand command){var user=users.findById(command.userId()).orElseThrow(()->new BusinessCommandRejectedException("APP_USER_NOT_FOUND","User not found"));var now=clock.now();if(!user.removeAvatar(now))return;media.activeByUser(command.userId()).ifPresent(item->{if(item.requestDeletion(now))media.save(item);});users.save(user);user.domainEvents().forEach(events::publish);user.clearDomainEvents();}}
